// chromly calibration repro — regress-567177599 (turbolev loop peeling phi type)
// Nguồn: test/mjsunit/turbolev/regress-567177599.js @ fix 41d0351e57 (fix sau checkout b8ffaab → bug có trong build hiện tại)
// Chạy: d8 --allow-natives-syntax --turbolev --abort-on-uncaught-exception repro.js

function assertEquals(a, b) {
  if (a !== b) throw new Error("assertEquals failed: expected " + b + " got " + a);
}
function assertFalse(x) {
  if (x) throw new Error("assertFalse failed");
}

var loop_value = 1.2;
var exit_value = 2.5;
loop_value = 1.4;
exit_value = 1.5;

const box = {value: 1.2};
const input = {[Symbol.toPrimitive]() { return box.value; }};

function store(n, input) {
  let value = 1.1;
  let sum = 0;
  while (n-- > 0) {
    sum += value;
    value = +input;
    loop_value = value;
  }
  exit_value = value;
  return sum;
}

%PrepareFunctionForOptimization(store);
store(3, input);

%OptimizeFunctionOnNextCall(store);
store(3, input);

box.value = 42;
store(3, input);
assertEquals(42, exit_value);
assertFalse(%IsSmi(exit_value));
print("REPRO-PASS");

// chromly calibration repro — regress-558568713 (parsing, PreparseDataBuilder size)
// Nguồn: test/mjsunit/regress/regress-558568713.js @ fix c2001427b7 (fix có trong checkout → revert để tái hiện)
// Chạy: d8 repro.js

function assertInstanceof(e, ctor) {
  if (!(e instanceof ctor)) throw new Error("assertInstanceof failed: " + e);
}

try {
  let padding = " ".repeat(270000000);
  let params = [];
  for (let i = 0; i < 16384; i++) {
    params.push("p" + i);
  }
  params.push("p16384=1");
  let param_str = params.join(",");
  let inner_funcs = "";
  for (let i = 0; i < 16400; i++) {
    inner_funcs += "function f" + i + "(){}\n";
  }
  let code = "function outer() {\n  function inner(" + param_str + ") {\n" + inner_funcs + "  }\n}\n";
  eval(padding + code);
} catch (e) {
  assertInstanceof(e, RangeError);
}
print("REPRO-DONE");

// chromly calibration repro — regress-556908674 (turboshaft load elimination)
// Nguồn: test/mjsunit/turboshaft/regress-556908674.js @ fix 1aaed11297 (revert để tái hiện)
// Flags: --allow-natives-syntax --turbofan --no-turboshaft-loop-unrolling (thêm --abort-on-uncaught-exception)

function assertEquals(a, b) {
  if (a !== b) throw new Error("assertEquals failed: " + a + " != " + b);
}

function f(o1, o2, n) {
  if (n) {
    let w = o1;
    w.p;
  } else {
    let w = o1;
    w.p;
  }

  let x = o1.p;
  let b = o2;
  let total = 0;
  for (let i = 0; i < 10; i++) {
    b.p = i;
    total += o1.p;
    if (i === 2) {
      o1.q = 5;
      b = o1;
    }
  }
  return total + x;
}

%PrepareFunctionForOptimization(f);
f({p: 7}, {p: 7, r: 1}, 0);
f({p: 7}, {p: 7, r: 1}, 1);
%OptimizeFunctionOnNextCall(f);

let res = f({p: 7}, {p: 7, r: 1}, 0);
assertEquals(70, res);
print("REPRO-DONE");

